// TH16 v1.00a st01bs.ecl BossCard1 -- spell 0
//   !EN 蝶符「ミニットスケールス」 / !HL 蝶符「アゲハの鱗粉」
// source: st01bs.ecl.txt:318-374 (BossCard1), 376-408 (BossCard1_at),
//         410-469 (BossCard1_at2); entry context st01bs.ecl.txt:8-78.
// Segment entry: independent boss at (0,128), speed 0, hurtbox r20 / hitbox r24,
// limit (0,128,240,64). Pre-segment clear/drop/transition is taken by the shell.

const TIME_LIMIT: int = 1624;   // 120 opening + 1500 source limit + 4 startup margin
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------------------
// Shell: control carrier for the segment events; the real boss is created after
// the opening buffer (validation.md shell).
// ---------------------------------------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_card1);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---------------------------------------------------------------------------
// BossCard1_at -- source 376-408.
// etAim(0,1) fixed-direction fan, base pi/2, spread A (1.3264502rad = 76deg)
// stepped by B (-0.12217305rad = -7deg) each wave; 6 ways x 3 layers;
// etSpeed(start, 3.0) with start 1.5 (Easy) / 2.5 (N/H/L); C = 7/10/11/11 waves.
// Source etAngle's pre-loop 0.6981317 is overwritten before the first etOn.
// ---------------------------------------------------------------------------
async sub card_at() {
    var rank: int = global(GVAR_RANK);
    var waves: int = 11;
    if rank <= RANK_EASY { waves = 7; }
    if rank == RANK_NORMAL { waves = 10; }
    var s0: fx = 2.5fx;
    if rank <= RANK_EASY { s0 = 1.5fx; }

    sh_reset(0);
    sh_sprite(0, TH16_RICE, 10);
    sh_ring(0, 0);              // source etAim(0,1): fixed-direction fan
    sh_aim(0, 0);
    sh_count(0, 6, 3);
    sh_speed(0, s0, (3fx - s0) / 2);   // source etSpeed(s0, 3.0), 3 layers

    var spread: int = 13835;    // 1.3264502rad in BAM
    for i in 0..waves {
        sh_angle(0, 90deg, spread as angle);
        sh_fire(0);
        spread = spread - 1274; // -0.12217305rad in BAM
        wait(10);
    }
}

// ---------------------------------------------------------------------------
// BossCard1_at2 -- source 410-469.
// wait(60); etAim(1,3) fixed ring, 1 way x (1/2/3) layers, base pi/2 with
// per-layer +0.034906585rad (2deg); etSpeed(start, 0.8) with start
// 1.0/1.0/2.0/3.0; floatTime(0,C,0,600,start,goal) writes start only:
// frames=0 disables later native writeback, so gap E/N=60, H/L=30; up to 6000 shots.
// circlePos gives a random disk point (RANDRAD, RANDF*128), etOffset uses
// (A, B*0.4).
// ---------------------------------------------------------------------------
async sub card_at2() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1fx;
    var gap: int = 60;
    if rank == RANK_HARD {
        layers = 2;
        s0 = 2fx;
        gap = 30;
    }
    if rank >= RANK_LUNATIC {
        layers = 3;
        s0 = 3fx;
        gap = 30;
    }

    wait(60);                   // source wait(60) before etNew(1)

    sh_reset(1);
    sh_sprite(1, TH16_BALL, 6);
    sh_ring(1, 1);              // source etAim(1,3): fixed ring
    sh_aim(1, 0);
    sh_count(1, 1, layers);
    sh_angle(1, 90deg, 2deg);   // source per-layer +0.034906585rad
    var step: fx = 0fx;
    if layers > 1 { step = (0.8fx - s0) / (layers - 1); }
    sh_speed(1, s0, step);      // source etSpeed(start, 0.8)

    // Native opcode91: source frames=0, mode=600. Keep C=start, not a ramp.

    var e: int = 6000;          // source $E = 6000
    while e > 0 {
        e = e - 1;
        var ra: int = rand(65536) - 32768;               // RANDRAD: -pi..pi
        var a: angle = ra as angle;
        var u: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;  // RANDF: 0..1
        var r: fx = u * 128fx;
        sh_offset(1, r * cos(a), r * sin(a) * 0.4fx);
        sh_fire(1);
        wait(gap);                                     // source $D = _S(%C)
    }
}

// ---------------------------------------------------------------------------
// BossCard1 main body -- source 318-374.
// ---------------------------------------------------------------------------
async sub boss_card1() {
    set_invuln(65535);
    set_hurtbox(20fx);          // source setHurtbox(40,40)
    set_hitbox(24fx);           // source setHitbox(48,48); body collision kept

    // source moveVel(0,0)/moveVelTime(0,0)/movePosTime(0,0) are entry-state
    // resets; movePosTime(60,4,0,128) is zero displacement from the given entry.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);

    wait(90);                   // source +90: time gate
    spawn card_at2();           // source @BossCard1_at2() async
    loop {
        spawn card_at();        // source BossCard1_1060
        card_wait(40);          // source wait(40)
        card_move_rand();       // source moveRand(60,4,1.0)
        card_wait(60);          // source wait(60)
    }
}

// ---------------------------------------------------------------------------
// moveRand(60,4,1.0) with moveLimit(0,128,240,64).
// Direction-selection inner region x +-60, y 112..144; clamped position
// x +-120, y 96..160. Speed decays linearly 1 -> 0 over 60 steps (mode 0
// inherited). Target phase 5 moves after ECL, so the next source step is
// armed in advance; every source wait uses card_wait.
// ---------------------------------------------------------------------------
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // source 412: signed unit random * pi, unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // source +-pi/2 guard, epsilon 0.05rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

